create extension if not exists pgcrypto;
create table if not exists public.spaces (id uuid primary key default gen_random_uuid(), name text not null default 'Our Space', created_by uuid not null references auth.users(id) on delete cascade, created_at timestamptz not null default now());
create table if not exists public.space_members (space_id uuid not null references public.spaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, display_name text not null, joined_at timestamptz not null default now(), primary key (space_id,user_id));
create table if not exists public.checkins (space_id uuid not null references public.spaces(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, energy smallint not null check (energy between 1 and 5), note text, updated_at timestamptz not null default now(), primary key (space_id,user_id));
create table if not exists public.bubbles (id uuid primary key default gen_random_uuid(), space_id uuid not null references public.spaces(id) on delete cascade, author_id uuid not null references auth.users(id) on delete cascade, content text not null check (char_length(content) between 1 and 2000), status text not null default 'shared' check (status in ('processing','shared','heard','talking','settled')), need text not null default 'listen' check (need in ('listen','comfort','space','solution','later')), position_x real not null default 50, position_y real not null default 50, size text not null default 'md' check (size in ('sm','md','lg')), tone text not null default 'violet' check (tone in ('violet','blue','rose','pearl')), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), resolved_at timestamptz);
create index if not exists bubbles_space_id_idx on public.bubbles(space_id);
create index if not exists checkins_space_id_idx on public.checkins(space_id);
create index if not exists space_members_user_id_idx on public.space_members(user_id);
